"""Colormap lookup tables for the PIL canvas: 8-bit RGB rows, low to high.

The tables are the published colour definitions of each map (viridis and the like at 256 rows,
the qualitative maps at their own number of colours). A ``_r`` suffix reverses a map.
"""

from __future__ import annotations

import numpy as np

_TABLES = {
    "viridis": "",
    "plasma": "",
    "RdYlGn": "",
    "coolwarm": "",
    "turbo": "",
    "jet": "",
    "Greys": "",
    "tab10": "1f77b4ff7f0e2ca02cd627289467bd8c564be377c27f7f7fbcbd2217becf",
    "tab20": "1f77b4aec7e8ff7f0effbb782ca02c98df8ad62728ff98969467bdc5b0d58c564bc49c94e377c2f7b6d27f7f7fc7c7c7bcbd22dbdb8d17becf9edae5",
    "Set1": "e41a1c377eb84daf4a984ea3ff7f00ffff33a65628f781bf999999",
    "Set2": "66c2a5fc8d628da0cbe78ac3a6d854ffd92fe5c494b3b3b3",
    "inferno": "",
    "magma": "",
    "RdBu": "",
    "YlOrRd": "",
    "Reds": "",
    "Blues": "",
}


def colormap(name: str) -> np.ndarray:
    """``(N, 3)`` uint8 rows of the named map, reversed for a ``_r`` suffix."""
    reverse = name.endswith("_r")
    key = name[:-2] if reverse else name
    if key not in _TABLES:
        raise KeyError(f"unknown colormap {name!r}; available: {sorted(_TABLES)}")
    table = np.frombuffer(bytes.fromhex(_TABLES[key]), dtype=np.uint8).reshape(-1, 3)
    return table[::-1] if reverse else table


def map_values(
    values: np.ndarray, name: str = "viridis", vmin: float | None = None, vmax: float | None = None
) -> np.ndarray:
    """``(..., 3)`` uint8 colours of ``values`` scaled from ``[vmin, vmax]`` (data range by default)."""
    values = np.asarray(values, dtype=np.float64)
    finite = values[np.isfinite(values)]
    low = float(finite.min()) if vmin is None and finite.size else (0.0 if vmin is None else vmin)
    high = float(finite.max()) if vmax is None and finite.size else (1.0 if vmax is None else vmax)
    table = colormap(name)
    scaled = (values - low) / (high - low) if high > low else np.zeros_like(values)
    index = np.clip(np.nan_to_num(scaled) * (len(table) - 1) + 0.5, 0, len(table) - 1).astype(int)
    return table[index]


def qualitative(name: str, index: int) -> str:
    """The ``index``-th colour of a qualitative map as ``#rrggbb``, cycling."""
    table = colormap(name)
    r, g, b = table[index % len(table)]
    return f"#{r:02x}{g:02x}{b:02x}"
